public DefaultParser(MediaTypeRegistry registry, ServiceLoader loader, Collection<Class<? extends Parser>> excludeParsers, EncodingDetector encodingDetector, Renderer renderer) {
    super(registry, getDefaultParsers(loader, encodingDetector, renderer, excludeParsers));
    this.loader = loader;
    this.excludedClasses = excludeParsers != null ? Collections.unmodifiableCollection(new ArrayList<>(excludeParsers)) : Collections.emptySet();
}
